import { request } from "../api/legacy.ts";
import type { Invoice } from "./types.ts";

function isInvoice(value: unknown): value is Invoice {
  if (typeof value !== "object" || value === null) return false;
  const v = value as Record<string, unknown>;
  return (
    typeof v.number === "string" &&
    typeof v.customer === "string" &&
    typeof v.totalCents === "number" &&
    Number.isFinite(v.totalCents)
  );
}

export async function loadInvoice(id: string): Promise<Invoice> {
  // `request` is typed Promise<any>; hold it as unknown until the guard runs (TS-2).
  const data: unknown = await request(`/invoices/${encodeURIComponent(id)}`);
  if (!isInvoice(data)) {
    throw new Error(`invoice ${id}: unexpected response shape from legacy service`);
  }
  return data;
}

