import { Controller, useForm } from "react-hook-form";
import { PhoneInput } from "../ui/PhoneInput.tsx";
import type { ContactValues } from "./contact.ts";

const PHONE_FIELDS = [
  { name: "phone", label: "Phone" },
  { name: "mobile", label: "Mobile" },
  { name: "fax", label: "Fax" },
] as const;

