      {PHONE_FIELDS.map(({ name, label }) => (
        <Controller
          key={name}
          name={name}
          control={control}
          rules={{ required: `${label} is required` }}
          render={({ field, fieldState }) => (
            <PhoneInput
              name={field.name}
              ref={field.ref}
              value={field.value}
              onChange={field.onChange}
              onBlur={field.onBlur}
              error={fieldState.error?.message}
            />
          )}
        />
      ))}
      <button type="submit">Save contact</button>
    </form>
  );
}

